import { sql } from 'drizzle-orm';
import type { SqliteRemoteDatabase } from 'drizzle-orm/sqlite-proxy';
import journal from '../../../../../../packages/db/migrations/meta/_journal.json';

/** A migration generated by drizzle-kit: its journal tag and timestamp and the whole SQL file. */
export interface BundledMigration {
  tag: string;
  /** `when` of the journal entry, stored as `created_at` in `__drizzle_migrations`. */
  when: number;
  sql: string;
}

const files = import.meta.glob<string>('../../../../../../packages/db/migrations/*.sql', {
  query: '?raw',
  import: 'default',
  eager: true,
});

/** SQL of `<tag>.sql`, read from the files that Vite bundled. */
function migrationFile(tag: string): string {
  const entry = Object.entries(files).find(([path]) => path.endsWith(`/${tag}.sql`));
  if (!entry) throw new Error(`Missing migration file ${tag}.sql`);
  return entry[1];
}

/**
 * The migrations of `packages/db` in journal order, bundled with the app: the same files the API applies
 * with drizzle's Node migrator, which reads them from disk (`node:fs`) and cannot run on the device.
 */
export const BUNDLED_MIGRATIONS: readonly BundledMigration[] = journal.entries.map((entry) => ({
  tag: entry.tag,
  when: entry.when,
  sql: migrationFile(entry.tag),
}));

/** Hex SHA-256 of the file, as drizzle's migrator stores it in `__drizzle_migrations.hash`. */
async function sha256(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

/**
 * Applies the pending `migrations` as drizzle's SQLite migrator does (`SQLiteAsyncDialect.migrate`), so a
 * local database ends up with the same schema and the same `__drizzle_migrations` rows as the API's:
 * those with a `when` newer than the last applied one run in a single transaction.
 */
export async function migrateLocal(
  db: SqliteRemoteDatabase<Record<string, unknown>>,
  migrations: readonly BundledMigration[],
): Promise<void> {
  // Same statement (whitespace included) as drizzle's, so `sqlite_master` matches the API's.
  await db.run(sql`
			CREATE TABLE IF NOT EXISTS ${sql.identifier('__drizzle_migrations')} (
				id SERIAL PRIMARY KEY,
				hash text NOT NULL,
				created_at numeric
			)
		`);
  const [last] = await db.values<[number, string, number | string]>(
    sql`SELECT id, hash, created_at FROM ${sql.identifier('__drizzle_migrations')} ORDER BY created_at DESC LIMIT 1`,
  );
  const pending = migrations.filter((migration) => !last || Number(last[2]) < migration.when);
  if (pending.length === 0) return;
  const hashes = await Promise.all(pending.map((migration) => sha256(migration.sql)));
  await db.transaction(async (tx) => {
    for (const [index, migration] of pending.entries()) {
      for (const statement of migration.sql.split('--> statement-breakpoint')) {
        await tx.run(sql.raw(statement));
      }
      await tx.run(
        sql`INSERT INTO ${sql.identifier('__drizzle_migrations')} ("hash", "created_at") VALUES(${hashes[index]}, ${migration.when})`,
      );
    }
  });
}
